132		right, err := buildValueExpr(call.Args[1], pc)
133		if err != nil {
134			return nil, err
135		}
136	
137		// The renderer expects a field/function/accessor on the left. A folded
138		// literal on the left (e.g. now.getMonth() == created_ts.getMonth()) swaps
139		// operands; two literals fold to a constant outcome.
140		if leftLit, ok := left.(*LiteralValue); ok {
141			if rightLit, ok := right.(*LiteralValue); ok {
142				outcome, err := compareLiterals(leftLit.Value, op, rightLit.Value)
143				if err != nil {
144					return nil, err
145				}
146				return &ConstantCondition{Value: outcome}, nil
147			}
148			left, right = right, left
149			op = mirrorComparisonOperator(op)
150		}
151	
152		// If the left side is a field, validate allowed operators.
153		if field, ok := left.(*FieldRef); ok {
154			def, exists := pc.schema.Field(field.Name)
155			if !exists {
156				return nil, errors.Errorf("unknown identifier %q", field.Name)
157			}
158			if def.Kind == FieldKindVirtualAlias {
159				def, exists = pc.schema.ResolveAlias(field.Name)
160				if !exists {
