162				}
163			}
164			if def.AllowedComparisonOps != nil {
165				if _, allowed := def.AllowedComparisonOps[op]; !allowed {
166					return nil, errors.Errorf("operator %s not allowed for field %q", op, field.Name)
167				}
168			}
169		}
